// The autogenerated GL thunk table is emitted in sorted name order.
#pragma once
#include <stddef.h>
#include <string.h>
#include "recomp_rt.h"

static inline const thunk_def *gl_find_sorted_thunk(const thunk_def *table,
                                                      size_t count, const char *name) {
    size_t lo = 0, hi = count;
    while (lo < hi) {
        const size_t mid = lo + (hi - lo) / 2;
        const int cmp = strcmp(table[mid].name, name);
        if (cmp == 0) return &table[mid];
        if (cmp < 0) lo = mid + 1;
        else hi = mid;
    }
    return NULL;
}
